<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class SalesReturnItem extends Model{protected $fillable=['product_id','quantity','unit_price','unit_cost','line_total'];protected function casts():array{return['quantity'=>'decimal:3','unit_price'=>'decimal:2','unit_cost'=>'decimal:2','line_total'=>'decimal:2'];}public function product(){return $this->belongsTo(Product::class);}public function salesReturn(){return $this->belongsTo(SalesReturn::class);}}
